// EP11 - compose the callback text for a missed call.
// Zero client data: everything here comes from the webhook body or the constants below.
const BUSINESS   = 'Ridgeline Roofing (demo)'; // fictional demo contractor - change to your trading name
const BOOK_LINK  = 'https://example.com/book';// your booking page (Calendly, form, whatever)
const TZ_OFFSET  = 8;                          // hours from UTC for "is it working hours"
const OPEN_HOUR  = 7;                          // 07:00 local
const CLOSE_HOUR = 19;                         // 19:00 local
const MISSED = ['no-answer', 'busy', 'failed', 'missed', 'voicemail', 'canceled'];

// One provider payload shape in, one flat shape out. Add a line per provider you use.
function normalise(b) {
  const g = (...keys) => keys.map(k => b[k]).find(v => v !== undefined && v !== null && v !== '');
  const status = String(
    g('call_status', 'CallStatus', 'status', 'event') ??
    (b.answered === false ? 'no-answer' : 'unknown')
  )
    .toLowerCase()
    .split('.').pop()          // 'call.missed' -> 'missed'
    .replace(/_/g, '-');       // 'no_answer'   -> 'no-answer'
  return {
    call_id:      String(g('call_id', 'CallSid', 'id', 'uuid') ?? 'no-call-id'),
    caller:       String(g('from', 'From', 'customer_phone_number', 'caller') ?? ''),
    called:       String(g('to', 'To', 'tracking_phone_number', 'called') ?? ''),
    call_status:  status,
    ring_seconds: Number(g('ring_seconds', 'RingDuration', 'duration', 'Duration') ?? 0) || 0,
  };
}

const nowUtc  = new Date();
const local   = new Date(nowUtc.getTime() + TZ_OFFSET * 3600 * 1000);
const hour    = local.getUTCHours();
const openNow = hour >= OPEN_HOUR && hour < CLOSE_HOUR;

return items.map(item => {
  const c = normalise(item.json.body ?? item.json);

  // E.164-ish sanity. No digits, no text - we never invent a destination number.
  const digits   = c.caller.replace(/[^0-9+]/g, '');
  const sendable = /^\+?[0-9]{7,15}$/.test(digits);
  const missed   = MISSED.includes(c.call_status);

  const action = !missed   ? 'ignored_not_a_missed_call'
               : !sendable ? 'ignored_unusable_number'
               :             'text_composed_simulated_send';

  const body = openNow
    ? `Sorry we missed your call - ${BUSINESS} here, we're on site. Want me to book you in? Reply YES or pick a slot: ${BOOK_LINK}`
    : `Sorry we missed your call - ${BUSINESS} here. We're off site for the night. Want me to book you in first thing? ${BOOK_LINK}`;

  return {
    json: {
      received_at:  nowUtc.toISOString(),
      call_id:      c.call_id,
      caller:       digits || c.caller,
      called:       c.called,
      call_status:  c.call_status,
      ring_seconds: c.ring_seconds,
      action,
      sms_to:       action === 'text_composed_simulated_send' ? digits : '',
      sms_body:     action === 'text_composed_simulated_send' ? body   : '',
      send_mode:    'SIMULATED - logged to ep11_missed_calls, nothing dialled',
      job_status:   missed && sendable ? 'needs_callback' : 'no_action',
      chars:        action === 'text_composed_simulated_send' ? body.length : 0,
    },
  };
});
